const nn=v=>Number(v||0);

/* Retail bill times: read time/at/ts/billTime, show IST, newest first */
function billMs(b){for(const k of ['time','at','ts','billTime']){let v=b[k];if(v==null||v==='')continue;if(typeof v==='number'||/^\d{9,13}(\.\d+)?$/.test(String(v))){v=Number(v);return v<1e11?v*1000:v}v=String(v).trim();if(/^\d{1,2}:\d{2}(:\d{2})?\s*([ap]\.?m\.?)?$/i.test(v))return {hm:v};let d=Date.parse(/(Z|[+-]\d{2}:?\d{2})$/i.test(v)?v:v.replace(' ','T')+'+05:30');if(!isNaN(d))return d}return null}
function fmtIst(ms){const d=new Date(ms+19800000);let h=d.getUTCHours();const m=String(d.getUTCMinutes()).padStart(2,'0'),ap=h>=12?'PM':'AM';h=h%12||12;return h+':'+m+' '+ap}
function hmMs(t){const m=String(t).match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*([ap])?/i);if(!m)return null;let h=+m[1];if(m[3]){const pm=/p/i.test(m[3]);h=h%12+(pm?12:0)}return h*60+(+m[2])}
function normBill(b){if(!b||typeof b!=='object'||b._tn)return;b._tn=1;const r=billMs(b);if(r==null)return;if(typeof r==='number'){b._ms=r;b.time=fmtIst(r)+' IST'}else{const mm=hmMs(r.hm);if(mm!=null){b._hm=mm;const h=Math.floor(mm/60);b.time=((h%12)||12)+':'+String(mm%60).padStart(2,'0')+' '+(h>=12?'PM':'AM')+' IST'}}if(b.seenAt===true||b.seenAt==='true'||b.seenAt===1||b.timeKind==='observed_in_read'||b.timeKind==='first_observed_in_read'){b.seenAt=true;if(b.time)b.time='observed in read '+String(b.time).replace(/ IST$/,'')}}
function bkey(b){return b._ms!=null?b._ms:(b._hm!=null?b._hm:null)}
function srtB(L){if(!L)return L;if(!L.some(b=>bkey(b)!=null))return L;return L.map((b,i)=>[b,i]).sort((x,y)=>{const a=bkey(x[0]),c=bkey(y[0]);return (c==null?-Infinity:c)-(a==null?-Infinity:a)||x[1]-y[1]}).map(x=>x[0])}
function normBills(){const R=data&&data.retail;const walk=o=>{if(!o||typeof o!=='object')return;if(Array.isArray(o)){o.forEach(walk);return}for(const k of Object.keys(o)){const v=o[k];if((k==='billList'||k==='bills')&&Array.isArray(v)){v.forEach(b=>{if(b&&typeof b==='object'&&b.seenAt==null&&(o.seenAt===true||o.seenAt==='true'))b.seenAt=true;normBill(b)});o[k]=srtB(v)}else if(v&&typeof v==='object')walk(v)}};walk(data&&data.retail);walk(data&&data.retailHistory)}
