function chatHtml(){
 const hi=`<div class="kb"><div class="askb">Good day, sir.</div><div class="kt">Ask me about sales, orders, SKUs, stock or payments, or type a command like "open orders".</div></div>`;
 const body=askLog.map((q,i)=>{let a;try{a=askAnswer(q)}catch(e){a=null}
  return `<div class="askq">${esc(q)}</div><div class="kb"><div class="askb">${a?VB[i%VB.length]:'My apologies, sir.'}</div>${a||`<div class="kt">I'm afraid I can't answer that yet. Try sales, orders, payments, SKUs, stock, top sellers or retail bills.</div>`}</div>`}).join('');
 return hi+body+(askLog.length?'<p class="kclr"><a href="#" id="askclr">Clear chat</a></p>':'')}
function askView(){return `<div class="chatwrap"><div id="chatlog">${chatHtml()}</div><div class="chatpad"></div></div>`}
function chatBar(){return `<div class="chatbar"><div class="askchips">${ASK_CHIPS.map(c=>`<button type="button" data-ak="${esc(c)}">${esc(c)}</button>`).join('')}</div><form id="askf"><input id="askin" type="text" autocomplete="off" autocapitalize="none" enterkeyhint="send" placeholder="Message Kingsley" value="${esc(askQ)}"><button id="asks" type="submit" aria-label="Send">&#8593;</button></form></div>`}
function chatRefresh(){const l=$('#chatlog');if(l){l.innerHTML=chatHtml();chatBindLog();chatBottom(true)}}
function chatBottom(sm){setTimeout(()=>window.scrollTo({top:document.documentElement.scrollHeight,behavior:sm?'smooth':'auto'}),30)}
function chatBindLog(){const c=$('#askclr');if(c)c.onclick=e=>{e.preventDefault();askLog=[];chatRefresh()}}
function bindAsk(){const f=$('#askf'),i=$('#askin');if(!f)return;i.oninput=()=>{askQ=i.value};
 const tb=document.querySelector('.tabbar');if(tb&&!document.body.classList.contains('chatkb'))document.documentElement.style.setProperty('--tbh',(innerHeight-tb.getBoundingClientRect().top+6)+'px');
 i.onfocus=()=>document.body.classList.add('chatkb');i.onblur=()=>setTimeout(()=>{if(document.activeElement!==i)document.body.classList.remove('chatkb')},150);
 const go=async t=>{t=String(t||'').trim();if(!t)return;askQ='';i.value='';let r=null;const n0=askLog.length;try{r=await vIntent(t)}catch(e){}if(askLog.length===n0){if(r&&r.say)toast(VB[Math.floor(Math.random()*VB.length)]+' '+r.say);else{askLog.push(t);if(askLog.length>12)askLog.shift();chatRefresh()}}};
 f.onsubmit=e=>{e.preventDefault();go(i.value)};
 document.querySelectorAll('[data-ak]').forEach(b=>b.onclick=()=>go(b.dataset.ak));
 chatBindLog();if(window.askStick){window.askStick=false;chatBottom(false)}}

